const source = $('Split Sources').item.json;
const run = $('Start Collection Run').item.json;
const rawLinks = Array.isArray($json.links) ? $json.links : [];
const seen = new Set();
const urls = [];
const clean = (value) => String(value ?? '').replace(/\s+/g, ' ').trim();
const decodeEntities = (value) => clean(value)
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>');
const stripTags = (html) => decodeEntities(String(html ?? '').replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' '));
const firstMatch = (html, patterns) => {
  for (const pattern of patterns) {
    const match = html.match(pattern);
    if (match && match[1]) return decodeEntities(match[1]);
  }
  return '';
};

for (const raw of rawLinks) {
  if (!raw || typeof raw !== 'string') continue;
  const trimmed = raw.trim();
  if (!trimmed || trimmed.startsWith('#')) continue;
  if (/^(mailto:|tel:|javascript:)/i.test(trimmed)) continue;

  let parsed;
  try {
    parsed = new URL(trimmed, source.website_url);
  } catch (error) {
    continue;
  }

  if (!['http:', 'https:'].includes(parsed.protocol)) continue;
  parsed.hash = '';
  const normalizedUrl = parsed.toString();
  if (seen.has(normalizedUrl)) continue;
  seen.add(normalizedUrl);
  urls.push(normalizedUrl);
}

const articles = [];
for (const url of urls) {
  try {
    const response = await fetch(url, {
      headers: { 'User-Agent': 'LGNM Website Collector/0.3 (+https://libyamonitor.local)' },
      redirect: 'follow',
    });
    const html = await response.text();
    const title = firstMatch(html, [
      /<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)["'][^>]*>/i,
      /<h1[^>]*>([\s\S]*?)<\/h1>/i,
      /<title[^>]*>([\s\S]*?)<\/title>/i,
    ]) || url;
    const rawDate = firstMatch(html, [
      /<meta[^>]+property=["']article:published_time["'][^>]+content=["']([^"']+)["'][^>]*>/i,
      /<time[^>]+datetime=["']([^"']+)["'][^>]*>/i,
      /<time[^>]*>([\s\S]*?)<\/time>/i,
    ]);
    let publishedAt = '';
    if (rawDate) {
      const parsedDate = new Date(rawDate);
      if (!Number.isNaN(parsedDate.getTime())) publishedAt = parsedDate.toISOString();
    }
    const articleHtml = firstMatch(html, [/<article[^>]*>([\s\S]*?)<\/article>/i, /<main[^>]*>([\s\S]*?)<\/main>/i]) || html;
    const content = stripTags(articleHtml);

    articles.push({
      url,
      title,
      published_at: publishedAt,
      content,
      metadata: {
        website_url: source.website_url,
        source_name: source.source_name,
        http_status: response.status,
        raw_publication_date: rawDate || null,
        pipeline: 'website_collection',
      },
    });
  } catch (error) {
    articles.push({
      url,
      title: url,
      published_at: '',
      content: '',
      metadata: {
        website_url: source.website_url,
        source_name: source.source_name,
        fetch_error: error.message,
        pipeline: 'website_collection',
      },
    });
  }
}

return [{
  json: {
    source_id: source.source_id,
    source_url_id: source.source_url_id,
    website_url: source.website_url,
    collection_run_id: run.collection_run_id,
    items_found: urls.length,
    articles,
  },
}];
